<script setup>
import {onMounted,ref} from 'vue'
import {api} from '../api'
import {auth,roleLabels} from '../composables/auth'
const props=defineProps({course:Object}),emit=defineEmits(['changed']),members=ref([]),accounts=ref([]),error=ref(''),notice=ref(''),busy=ref(false),form=ref({userId:'',courseRole:'student'})
const roles={teacher:'授課教師',ta:'課程助教',student:'學生'}
async function load(){try{members.value=await api(`/courses/${props.course.id}/members`);if(props.course.isOwner)accounts.value=await api(`/courses/${props.course.id}/eligible-accounts`)}catch(e){error.value=e.message}}
async function enroll(){busy.value=true;error.value='';notice.value='';try{await api(`/courses/${props.course.id}/members`,{method:'POST',body:form.value});form.value.userId='';await load();emit('changed');notice.value='本課程學員與角色已更新。'}catch(e){error.value=e.message}finally{busy.value=false}}
const capabilities={materials:'教材編輯',assessments:'評量設定',grading:'登分及發布項目成績',statistics:'教材學習統計'}
async function restrictions(member){busy.value=true;try{await api('/courses/'+props.course.id+'/members/'+member.id+'/ta-restrictions',{method:'PUT',body:member.taRestrictions});notice.value='已儲存本課助教權限。'}catch(e){error.value=e.message;await load()}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="surface form-surface"><h2>課程學員與教學成員</h2><p class="muted">此名單僅屬於「{{course.title}}」。課程角色與平台角色分開管理。</p><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><form v-if="course.isOwner && course.status!=='archived'" @submit.prevent="enroll"><div class="form-grid"><label>加入學員／教學成員<select aria-label="加入課程帳號" v-model="form.userId" required><option value="">請選擇帳號</option><option v-for="u in accounts" :key="u.id" :value="u.id">{{u.displayName}} · {{u.email}}</option></select></label><label>課程角色<select aria-label="加入課程角色" v-model="form.courseRole"><option v-for="(label,key) in roles" :key="key" :value="key">{{label}}</option></select></label></div><button class="button primary" :disabled="busy">加入／更新課程學員</button><p class="field-hint">沒有帳號時，請聯絡平台管理員建立。</p></form><p v-else class="field-hint">由課程擁有者安排課程學員與角色。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>姓名</th><th>電子郵件</th><th>課程角色</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.displayName}} <RouterLink v-if="m.courseRole==='student'" :to="{path:`/learners/${m.id}`,query:{course:course.id}}">學員檔案</RouterLink></td><td>{{m.email}}</td><td>{{roles[m.courseRole]}}<details v-if="m.courseRole==='ta'&&course.isOwner&&course.status!=='archived'"><summary>本課助教權限</summary><fieldset><legend>停用下列權限</legend><label v-for="(label,k) in capabilities" :key="k"><input type="checkbox" v-model="m.taRestrictions" :value="k"/>{{label}}</label></fieldset><button :disabled="busy" @click="restrictions(m)">儲存助教權限</button></details></td></tr></tbody></table></div></section></template>
